    letter-spacing: var(--cui-sidebar-group-label-letter-spacing);
    text-transform: var(--cui-sidebar-group-label-text-transform);
  }

  :where([data-control-family="sidebar"][data-slot="menu-button"]) {
    inline-size: 100%;
    gap: calc(var(--spacing) * 1.5);
    block-size: var(--cui-sidebar-menu-button-height);
