    font-weight: var(--cui-sidebar-menu-button-font-weight);
    background-color: transparent;
    color: var(--cui-sidebar-menu-button-foreground);
  }

  :where([data-control-family="sidebar"][data-slot="menu-button"][data-size="sm"]) {
    --cui-sidebar-menu-button-height: var(--control-h-sm);
    --cui-sidebar-menu-button-font-size: var(--text-label);
  }

  :where([data-control-family="sidebar"][data-slot="menu-button"][data-size="lg"]) {
    --cui-sidebar-menu-button-height: var(--control-h-lg);
    gap: calc(var(--spacing) * 2);
  }

  :where(
    [data-control-family="sidebar"][data-collapsible="icon"] [data-control-family="sidebar"][data-slot="menu-button"] > :not(:first-child)
  ) {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    opacity: 0;
    white-space: nowrap;
  }

  :where([data-control-family="sidebar"][data-slot="menu-action"]) {
    inset-block-start: calc(var(--control-h-md) / 2);
    padding: 0;
    border-radius: var(--cui-sidebar-menu-button-radius);
