  :where([data-control-family="sidebar"][data-slot="menu-button"][data-active] ~ [data-slot="menu-action"]) {
    color: var(--cui-sidebar-menu-button-active-foreground);
  }

  :where(
    [data-control-family="sidebar"][data-slot="menu-button"]:is([data-indicator="slide"], [data-indicator="hover"])[data-active]
      ~ [data-slot="menu-action"]
  ) {
    color: var(--cui-sidebar-menu-button-track-active-foreground);
  }

  :where([data-control-family="sidebar"][data-slot="menu-action"])::before {
    content: "";
    position: absolute;
    inset-block-start: 50%;
    inset-inline-start: 50%;
    translate: -50% -50%;
    inline-size: max(100%, var(--target-min));
    block-size: max(100%, var(--target-min));
  }

  :where([data-control-family="sidebar"][data-slot="menu-action"]:dir(rtl))::before {
    translate: 50% -50%;
  }

  @media (hover: hover) {
    :where(
        [data-control-family="sidebar"]:is([data-slot="menu-button"], [data-slot="menu-action"]):hover:not(
          :disabled,
          [data-disabled],
          [aria-disabled="true"]
        )
      ) {
      background-color: var(--cui-sidebar-menu-button-hover-background);
      color: var(--cui-sidebar-menu-button-hover-foreground);
      box-shadow: var(--cui-sidebar-menu-button-hover-shadow);
    }

    :where(
        [data-control-family="sidebar"][data-slot="menu-button"][data-state="open"]:hover:not(
          :disabled,
          [data-disabled],
          [aria-disabled="true"]
        )
      ) {
      background-color: var(--cui-sidebar-menu-button-active-background);
      color: var(--cui-sidebar-menu-button-active-foreground);
    }
  }

  :where([data-control-family="sidebar"][data-slot="menu-action"]:is(:active, [data-popup-open])),
  :where([data-control-family="sidebar"][data-slot="menu-button"]:active),
  :where([data-control-family="sidebar"][data-slot="menu-button"][data-active]) {
    background-color: var(--cui-sidebar-menu-button-active-background);
    color: var(--cui-sidebar-menu-button-active-foreground);
    box-shadow: var(--cui-sidebar-menu-button-active-shadow);
  }

  :where([data-control-family="sidebar"][data-slot="menu-button"][data-active]) {
    font-weight: var(--cui-sidebar-menu-button-active-font-weight);
  }

  :where([data-control-family="sidebar"][data-slot="menu-button"][data-variant="outline"]) {
    background-color: var(--background);
    box-shadow: 0 0 0 1px var(--sidebar-border);
  }

  @media (hover: hover) {
    :where(
        [data-control-family="sidebar"][data-slot="menu-button"][data-variant="outline"]:hover:not(
          :disabled,
          [data-disabled],
          [aria-disabled="true"]
        )
      ) {
      box-shadow: 0 0 0 1px oklch(from var(--foreground) l c h / 0.08);
    }
  }

  :where(
    [data-control-family="sidebar"][data-slot="menu-button"][data-indicator="slide"]:is(:hover, :active, [data-active], [data-popup-open])
  ) {
    background-color: transparent;
  }

  :where([data-control-family="sidebar"][data-slot="menu-button"]:is([data-indicator="slide"], [data-indicator="hover"])[data-active]) {
    color: var(--cui-sidebar-menu-button-track-active-foreground);
  }

  :where(
    [data-control-family="sidebar"][data-slot="menu-button"][data-indicator="hover"]:focus-visible:not(
      [data-active],
      :disabled,
      [data-disabled],
      [aria-disabled="true"]
    )
  ) {
    background-color: var(--cui-sidebar-menu-button-hover-background);
    color: var(--cui-sidebar-menu-button-hover-foreground);
    box-shadow: var(--cui-sidebar-menu-button-hover-shadow);
  }

  @media (hover: hover) {
    :where(
        [data-control-family="sidebar"][data-slot="menu"][data-indicator="hover"]:has(
            > [data-slot="menu-item"] > [data-slot="menu-button"]:focus-visible
          )
          > [data-slot="menu-item"]
          > [data-slot="menu-button"][data-indicator="hover"]:hover:not([data-active], :focus-visible)
      ) {
      background-color: transparent;
      box-shadow: none;
    }
  }

  :where([data-control-family="sidebar"][data-slot="menu-action"]:is(:disabled, [aria-disabled="true"])),
  :where([data-control-family="sidebar"][data-slot="menu-button"]:disabled),
  :where([data-control-family="sidebar"][data-slot="menu-button"][aria-disabled="true"]) {
    opacity: var(--disabled-opacity);
  }

  :where([data-control-family="sidebar"][data-slot="group-content"]) {
    font-size: var(--text-body);
  }

  :where([data-control-family="sidebar"][data-slot="menu-button"][data-size="sm"] ~ [data-slot="menu-action"]) {
    inset-block-start: calc(var(--control-h-sm) / 2);
  }

  :where([data-control-family="sidebar"][data-slot="menu-button"][data-size="lg"] ~ [data-slot="menu-action"]) {
    inset-block-start: calc(var(--control-h-lg) / 2);
  }

  :where([data-control-family="sidebar"][data-slot="menu-button"]:has(~ [data-slot="menu-action"])) {
    padding-inline-end: calc(var(--spacing) * 8);
  }

  :where([data-control-family="sidebar"][data-slot="menu-badge"]) {
    inset-block-start: calc(var(--control-h-md) / 2);
    inset-inline-end: calc(var(--spacing) * 1);
    min-inline-size: var(--cui-sidebar-menu-badge-height);
    block-size: var(--cui-sidebar-menu-badge-height);
    padding-inline: calc(var(--spacing) * 1.5);
    border-radius: 9999px;
    background-color: var(--cui-sidebar-menu-badge-background);
    color: var(--cui-sidebar-menu-badge-foreground);
    font-size: var(--text-caption);
    font-weight: var(--font-weight-medium);
    line-height: 1;
    transition: opacity var(--duration-fast) var(--ease-standard);
  }

  :where([data-control-family="sidebar"][data-slot="menu-button"][data-size="sm"] ~ [data-slot="menu-badge"]) {
    inset-block-start: calc(var(--control-h-sm) / 2);
  }

  :where([data-control-family="sidebar"][data-slot="menu-button"][data-size="lg"] ~ [data-slot="menu-badge"]) {
    inset-block-start: calc(var(--control-h-lg) / 2);
  }

  :where([data-control-family="sidebar"][data-slot="menu-button"]:has(~ [data-slot="menu-badge"])) {
    padding-inline-end: calc(var(--spacing) * 10);
  }

  :where(
    [data-control-family="sidebar"][data-slot="menu-button"]:has(~ [data-slot="menu-badge"]):has(
      ~ [data-slot="menu-action"]:not([data-show-on-hover])
    )
  ) {
    padding-inline-end: calc(var(--spacing) * 16);
  }

  :where(
    [data-control-family="sidebar"][data-slot="menu-item"]:has(> [data-slot="menu-action"]:not([data-show-on-hover]))
      > [data-slot="menu-badge"]
  ) {
    inset-inline-end: calc(var(--spacing) * 7);
  }

  @media (hover: hover) and (pointer: fine) {
    :where([data-control-family="sidebar"][data-slot="menu-action"][data-show-on-hover]) {
      opacity: 0;
    }

    :where([data-control-family="sidebar"][data-slot="menu-item"]:is(:hover, :focus-within) [data-slot="menu-action"]),
    :where([data-control-family="sidebar"][data-slot="menu-action"][data-popup-open]) {
      opacity: 1;
    }

    :where(
        [data-control-family="sidebar"][data-slot="menu-item"]:is(
            :hover,
            :focus-within,
            :has(> [data-slot="menu-action"][data-popup-open])
          ):has(> [data-slot="menu-action"][data-show-on-hover])
          > [data-slot="menu-badge"]
      ) {
      opacity: 0;
    }
  }

  @media (pointer: coarse) {
    :where([data-control-family="sidebar"][data-slot="menu-action"]) {
      min-inline-size: var(--touch-target);
      min-block-size: var(--touch-target);
      inset-inline-end: 0;
      inset-block-start: max(calc(var(--touch-target) / 2), calc(var(--control-h-md) / 2));
    }

    :where([data-control-family="sidebar"][data-slot="menu-button"][data-size="sm"] ~ [data-slot="menu-action"]) {
      inset-block-start: max(calc(var(--touch-target) / 2), calc(var(--control-h-sm) / 2));
    }

    :where([data-control-family="sidebar"][data-slot="menu-button"][data-size="lg"] ~ [data-slot="menu-action"]) {
      inset-block-start: max(calc(var(--touch-target) / 2), calc(var(--control-h-lg) / 2));
    }

    :where([data-control-family="sidebar"][data-slot="menu-button"]:has(~ [data-slot="menu-action"])) {
      padding-inline-end: calc(var(--spacing) * 12);
    }

    :where([data-control-family="sidebar"][data-slot="menu-item"]:has(> [data-slot="menu-action"]) > [data-slot="menu-badge"]) {
      inset-inline-end: var(--touch-target);
      inset-block-start: max(calc(var(--touch-target) / 2), calc(var(--control-h-md) / 2));
    }

    :where([data-control-family="sidebar"][data-slot="menu-button"]:has(~ [data-slot="menu-badge"]):has(~ [data-slot="menu-action"])) {
      padding-inline-end: calc(var(--touch-target) + var(--spacing) * 10);
    }
  }

  :where([data-control-family="sidebar"][data-collapsible="icon"] [data-control-family="sidebar"][data-slot="menu-button"]) {
    --cui-sidebar-menu-button-padding-inline: 0px;
    inline-size: calc(var(--sidebar-width-icon) - var(--spacing) * 4);
    max-inline-size: 100%;
    padding-inline: var(--cui-sidebar-menu-button-padding-inline);
    justify-content: center;
    gap: 0;
    overflow: visible;
  }
}

@layer components {
  :where([data-control-family="sidebar"][data-slot="wrapper"]) {
    --cui-sidebar-nav-height: 4.5rem;
    --cui-sidebar-nav-background: var(--sidebar);
    --cui-sidebar-nav-foreground: var(--sidebar-foreground);
    --cui-sidebar-nav-border-color: var(--sidebar-border);
    --cui-sidebar-nav-border-width: var(--control-rim-width);
    --cui-sidebar-nav-shadow: var(--shadow-md);
    --cui-sidebar-nav-item-radius: var(--radius-control);
    --cui-sidebar-nav-item-active-background: var(--active-fill);
    --cui-sidebar-nav-item-active-foreground: var(--foreground);
    --cui-sidebar-nav-gap: calc(var(--spacing) * 3);
  }

  :where([data-control-family="sidebar"][data-slot="mobile-nav-container"]) {
    --_sidebar-nav-space: calc(var(--cui-sidebar-nav-height) + env(safe-area-inset-bottom, 0px));
    block-size: var(--_sidebar-nav-space);
  }

  :where([data-control-family="sidebar"][data-slot="mobile-nav"]) {
    position: fixed;
    inset-block-end: 0;
    inset-inline: 0;
    z-index: 30;
    min-block-size: var(--_sidebar-nav-space);
    gap: calc(var(--spacing) * 1);
    padding: calc(var(--spacing) * 1) max(calc(var(--spacing) * 2), env(safe-area-inset-right, 0px))
      calc(var(--spacing) * 1 + env(safe-area-inset-bottom, 0px)) max(calc(var(--spacing) * 2), env(safe-area-inset-left, 0px));
    background-color: var(--cui-sidebar-nav-background);
    color: var(--cui-sidebar-nav-foreground);
  }

  :where([data-control-family="sidebar"][data-slot="mobile-nav"][data-variant="bar"]) {
    border-block-start: var(--cui-sidebar-nav-border-width) solid var(--cui-sidebar-nav-border-color);
  }

  :where([data-control-family="sidebar"][data-slot="mobile-nav-container"][data-layout="contained"] > [data-slot="mobile-nav"]) {
    position: absolute;
  }

  :where([data-control-family="sidebar"][data-slot="mobile-nav"] [data-mobile-nav-item]) {
    display: flex;
    flex: 1 1 0;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: calc(var(--spacing) * 1);
    min-inline-size: 48px;
    min-block-size: 48px;
    block-size: auto;
    padding: calc(var(--spacing) * 1);
    border-radius: var(--cui-sidebar-nav-item-radius);
    background-color: transparent;
    color: var(--cui-sidebar-nav-foreground);
    font-size: var(--text-caption);
    font-weight: var(--font-weight-medium);
    text-decoration: none;
    text-align: center;
  }

  :where([data-control-family="sidebar"][data-slot="mobile-nav"] [data-mobile-nav-item] > svg) {
    inline-size: calc(var(--spacing) * 5);
    block-size: calc(var(--spacing) * 5);
    flex-shrink: 0;
  }

  :where([data-control-family="sidebar"][data-slot="mobile-nav"] [data-mobile-nav-item] > span) {
    max-inline-size: 100%;
  }

  :where([data-control-family="sidebar"][data-slot="mobile-nav"] [data-mobile-nav-item][data-active]) {
    background-color: var(--cui-sidebar-nav-item-active-background);
    color: var(--cui-sidebar-nav-item-active-foreground);
  }

  :where([data-control-family="sidebar"][data-slot="mobile-nav"] [data-mobile-nav-item]:is(:disabled, [aria-disabled="true"])) {
    pointer-events: none;
    opacity: 0.5;
  }

  :where([data-control-family="sidebar"][data-slot="mobile-nav-container"][data-variant="floating"]) {
    block-size: calc(var(--_sidebar-nav-space) + var(--cui-sidebar-nav-gap));
  }

  :where([data-control-family="sidebar"][data-slot="mobile-nav"][data-variant="floating"]) {
    inset-inline-start: auto;
    inset-inline-end: max(var(--cui-sidebar-nav-gap), env(safe-area-inset-right, 0px));
    inset-block-end: calc(var(--cui-sidebar-nav-gap) + env(safe-area-inset-bottom, 0px));
    min-block-size: 0;
    padding: calc(var(--spacing) * 1);
    border: var(--cui-sidebar-nav-border-width) solid var(--cui-sidebar-nav-border-color);
    border-radius: var(--cui-sidebar-nav-item-radius);
    box-shadow: var(--cui-sidebar-nav-shadow);
  }

  @media (width < 64rem) {
    :where([data-control-family="sidebar"][data-slot="wrapper"]:has(> [data-slot="mobile-nav-container"])) {
      flex-direction: column;
    }

    :where([data-control-family="sidebar"][data-slot="wrapper"]:has(> [data-slot="mobile-nav-container"]) > [data-slot="inset"]) {
      scroll-padding-block-end: calc(var(--cui-sidebar-nav-height) + env(safe-area-inset-bottom, 0px));
    }
  }

  @media (hover: hover) {
    :where([data-control-family="sidebar"][data-slot="mobile-nav"] [data-mobile-nav-item]:hover) {
      background-color: var(--cui-sidebar-nav-item-active-background);
      color: var(--cui-sidebar-nav-item-active-foreground);
    }
  }
}

