@layer components {
  :where([data-control-family="sidebar"][data-slot="root"]) {
    --_sidebar-transition-duration: var(--duration-base);
  }

  :where([data-control-family="sidebar"][data-slot="root"]:has(> [data-slot="container"] > div > [data-slot="rail"]:focus-visible)) {
    --_sidebar-transition-duration: 0s;
  }

  :where([data-control-family="sidebar"][data-slot="container"]) {
    translate: 0;
    transition:
      width var(--_sidebar-transition-duration) var(--ease-standard),
      translate var(--_sidebar-transition-duration) var(--ease-standard);
  }

  :where([data-control-family="sidebar"][data-slot="inner"]) {
    transition: padding var(--_sidebar-transition-duration) var(--ease-standard);
  }

  :where([data-control-family="sidebar"][data-collapsible="offcanvas"][data-side="left"]:dir(ltr) [data-slot="container"]),
  :where([data-control-family="sidebar"][data-collapsible="offcanvas"][data-side="right"]:dir(rtl) [data-slot="container"]) {
    translate: -100% 0;
  }

  :where([data-control-family="sidebar"][data-collapsible="offcanvas"][data-side="right"]:dir(ltr) [data-slot="container"]),
  :where([data-control-family="sidebar"][data-collapsible="offcanvas"][data-side="left"]:dir(rtl) [data-slot="container"]) {
    translate: 100% 0;
  }

  :where(
    [data-control-family="sidebar"][data-slot="wrapper"][data-resizing]
      [data-control-family="sidebar"]:is([data-slot="container"], [data-slot="gap"], [data-slot="inner"])
  ) {
    transition: none;
  }

  @media (prefers-reduced-motion: reduce) {
    :where([data-control-family="sidebar"]:is([data-slot="container"], [data-slot="gap"], [data-slot="inner"])) {
      transition: none;
    }
  }

  :where([data-control-family="sidebar"][data-slot="rail"]) {
    inline-size: calc(var(--spacing) * 4);
    background-image: linear-gradient(var(--cui-sidebar-rail-divider-background), var(--cui-sidebar-rail-divider-background));
    background-position: center;
    background-repeat: no-repeat;
    background-size: 2px 100%;
  }

  :where([data-control-family="sidebar"][data-collapsible="offcanvas"] [data-slot="rail"]) {
    background-position: right;
  }

  :where([data-control-family="sidebar"][data-collapsible="offcanvas"] [data-slot="rail"]:dir(rtl)) {
    background-position: left;
  }

  @media (hover: hover) {
    :where([data-control-family="sidebar"][data-slot="rail"]:hover) {
      --cui-sidebar-rail-divider-background: var(--sidebar-border);
    }

    :where([data-control-family="sidebar"][data-collapsible="offcanvas"] [data-slot="rail"]:not([data-resizable]):hover) {
      background-color: var(--sidebar);
    }
  }

  :where([data-control-family="sidebar"][data-slot="rail"][data-resizable]) {
    inline-size: calc(var(--spacing) * 2);
    background: none;
  }

  :where([data-control-family="sidebar"][data-slot="rail"][data-resizable])::after {
    content: "";
    position: absolute;
    inset-block: 12.5%;
    inset-inline-start: 50%;
    inline-size: 1px;
    background-image: linear-gradient(transparent, var(--cui-sidebar-rail-divider-background), transparent);
  }

  :where([data-control-family="sidebar"][data-slot="rail"]:is(:focus-visible, [data-resizing="true"])) {
    --cui-sidebar-rail-divider-background: var(--focus-ring);
  }

  :where([data-control-family="sidebar"][data-slot="inset"]) {
    background-color: var(--cui-sidebar-inset-background);
    background-image: var(--cui-sidebar-inset-background-image);
