"use client";

import { useRender } from "@base-ui/react/use-render";
import type { ComponentProps, CSSProperties, MouseEvent, RefObject } from "react";
import { createContext, useContext, useEffect, useId, useLayoutEffect, useRef, useState } from "react";
import { SIDEBAR_COOKIE_NAME } from "@/components/control-ui/control-props";
import { useIsMobile } from "@/components/control-ui/hooks/use-mobile";
import type { SidebarKnobStyle } from "@/components/control-ui/knob-contracts/sidebar-knobs";
import { cn } from "@/components/control-ui/lib/cn";
import { useSkin } from "@/components/control-ui/skin-provider";

import { TooltipProvider } from "@/components/control-ui/ui/tooltip";

const SIDEBAR_COOKIE_MAX_AGE = 60 * 60 * 24 * 7;

export type SidebarStyle = CSSProperties &
  SidebarKnobStyle & {
    "--sidebar-width"?: string;
    "--sidebar-width-icon"?: string;
  };

const SIDEBAR_WIDTH = "16rem";
const SIDEBAR_WIDTH_ICON = "3rem";
const SIDEBAR_KEYBOARD_SHORTCUT = "b";
const SIDEBAR_MOBILE_BREAKPOINT = "--breakpoint-lg";

export type SidebarLayoutMode = "viewport" | "contained";

type SidebarContextProps = {
  state: "expanded" | "collapsed";
  open: boolean;
  setOpen: (open: boolean) => void;
  openMobile: boolean;
  setOpenMobile: (open: boolean) => void;
  isMobile: boolean;
  toggleSidebar: () => void;
  width: number | undefined;
  minWidth: number;
  maxWidth: number;
  setWidth: (width: number) => void;
  layout: SidebarLayoutMode;
  keyboardShortcut: string | null;
  sidebarId: string;
  contentId: string;
};

type SidebarElements = {
  wrapperRef: RefObject<HTMLDivElement | null>;
  offcanvasRef: RefObject<HTMLDivElement | null>;
  railRef: RefObject<HTMLElement | null>;
  triggerRef: RefObject<HTMLButtonElement | null>;
  activeTriggerRef: RefObject<HTMLButtonElement | null>;
  insetRef: RefObject<HTMLElement | null>;
};

const SidebarElementsContext = createContext<SidebarElements | null>(null);
export const SidebarSurfaceContext = createContext<{
  side: "left" | "right";
  collapsible: "offcanvas" | "icon" | "none";
  railContainer: HTMLDivElement | null;
} | null>(null);

export function useSidebarElements() {
  const elements = useContext(SidebarElementsContext);
  if (!elements) throw new Error("Sidebar parts must be used within a SidebarProvider.");
  return elements;
}

export function useSidebarSurface() {
  const surface = useContext(SidebarSurfaceContext);
  if (!surface) throw new Error("SidebarRail must be used within a Sidebar.");
  return surface;
}

function focusOutsideCollapsedContent({
  offcanvasRef,
  railRef,
  triggerRef,
}: Pick<SidebarElements, "offcanvasRef" | "railRef" | "triggerRef">) {
  const container = offcanvasRef.current;
  if (!container?.contains(document.activeElement)) return;
  const target = railRef.current ?? triggerRef.current;
  if (target) target.focus({ preventScroll: true });
  else container.focus({ preventScroll: true });
}

const SidebarContext = createContext<SidebarContextProps | null>(null);

export function useSidebar() {
  const context = useContext(SidebarContext);
  if (!context) {
    throw new Error("useSidebar must be used within a SidebarProvider.");
  }

  return context;
}

export type SidebarProviderProps = Omit<ComponentProps<"div">, "style"> & {
  defaultOpen?: boolean;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  defaultWidth?: number;
  minWidth?: number;
  maxWidth?: number;
  width?: number;
  onWidthChange?: (width: number) => void;
  persistOpen?: boolean;
  keyboardShortcut?: string | null;
  layout?: SidebarLayoutMode;
  skipLinkLabel?: string;
  contentId?: string;
  style?: SidebarStyle;
};

export function SidebarProvider({
  defaultOpen = true,
  open: openProp,
  onOpenChange,
  defaultWidth,
  minWidth = 224,
  maxWidth = 420,
  width: widthProp,
  onWidthChange,
  persistOpen = true,
  keyboardShortcut = SIDEBAR_KEYBOARD_SHORTCUT,
  layout = "viewport",
  skipLinkLabel = "Skip to content",
  contentId: contentIdProp,
  ref,
  className,
  style,
  children,
  ...props
}: SidebarProviderProps) {
  const skin = useSkin();
  const isMobile = useIsMobile(SIDEBAR_MOBILE_BREAKPOINT);
  const [openMobile, setOpenMobile] = useState(false);
  if (!isMobile && openMobile) setOpenMobile(false);
  const wrapperRef = useRef<HTMLDivElement>(null);
  const offcanvasRef = useRef<HTMLDivElement>(null);
  const railRef = useRef<HTMLElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const activeTriggerRef = useRef<HTMLButtonElement>(null);
  const insetRef = useRef<HTMLElement>(null);
  const elements = { wrapperRef, offcanvasRef, railRef, triggerRef, activeTriggerRef, insetRef };
  const sidebarId = useId();
  const generatedContentId = useId();
  const contentId = contentIdProp ?? generatedContentId;
  const [internalWidth, setInternalWidth] = useState(defaultWidth);
  function clampWidth(nextWidth: number) {
    return Math.min(maxWidth, Math.max(minWidth, nextWidth));
  }
  const requestedWidth = widthProp ?? internalWidth;
  const width = requestedWidth === undefined ? undefined : clampWidth(requestedWidth);
  function setWidth(nextWidth: number) {
    const clampedWidth = clampWidth(nextWidth);
    if (widthProp === undefined) setInternalWidth(clampedWidth);
    onWidthChange?.(clampedWidth);
  }

  const [internalOpen, setInternalOpen] = useState(defaultOpen);
  const open = openProp ?? internalOpen;
  useLayoutEffect(() => {
    if (!open && !isMobile) focusOutsideCollapsedContent({ offcanvasRef, railRef, triggerRef });
  }, [open, isMobile]);

  const setOpen = (value: boolean | ((value: boolean) => boolean)) => {
    const openState = typeof value === "function" ? value(open) : value;
    if (!openState && !isMobile) focusOutsideCollapsedContent(elements);
    if (openProp === undefined) setInternalOpen(openState);
    onOpenChange?.(openState);
    if (persistOpen) {
      // biome-ignore lint/suspicious/noDocumentCookie: Cookie Store API isn't cross-browser yet.
      document.cookie = `${SIDEBAR_COOKIE_NAME}=${openState}; path=/; max-age=${SIDEBAR_COOKIE_MAX_AGE}`;
    }
  };

  const toggleSidebar = () => (isMobile ? setOpenMobile((prev) => !prev) : setOpen(!open));

  const toggleRef = useRef(toggleSidebar);
  useEffect(() => {
    toggleRef.current = toggleSidebar;
  });

  useEffect(() => {
    if (keyboardShortcut === null) return;
    const shortcut = keyboardShortcut.toLowerCase();

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.defaultPrevented || event.repeat || event.altKey || event.shiftKey) return;
      if (!(event.metaKey || event.ctrlKey) || event.key.toLowerCase() !== shortcut) return;
      const target = event.target;
      if (target instanceof HTMLElement && (target.isContentEditable || target.closest("input, textarea, select") !== null)) return;
      event.preventDefault();
      toggleRef.current();
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [keyboardShortcut]);

  const state = open ? "expanded" : "collapsed";

  const contextValue: SidebarContextProps = {
    state,
    open,
    setOpen,
    isMobile,
    openMobile,
    setOpenMobile,
    toggleSidebar,
    width,
    setWidth,
    minWidth,
    maxWidth,
    layout,
    keyboardShortcut,
    sidebarId,
    contentId,
  };

  const wrapperStyle: SidebarStyle = {
    "--sidebar-width": skin.sidebarWidth ?? SIDEBAR_WIDTH,
    "--sidebar-width-icon": SIDEBAR_WIDTH_ICON,
    ...style,
    ...(width === undefined ? {} : { "--sidebar-width": `${width}px` }),
  };

  function skipToContent(event: MouseEvent<HTMLAnchorElement>) {
    const inset = insetRef.current;
    if (!inset) return;
    event.preventDefault();
    inset.focus();
  }

  const wrapper = useRender({
    defaultTagName: "div",
    ref: [ref ?? null, wrapperRef],
    props: {
      ...props,
      "data-control-ui": "sidebar",
      "data-control-family": "sidebar",
      "data-slot": "wrapper",
      "data-layout": layout,
      style: wrapperStyle,
      className: cn(
        "group/sidebar-wrapper relative flex w-full",
        layout === "contained" ? "h-full min-h-0 overflow-hidden" : "min-h-svh",
        className,
      ),
      children: (
        <>
          <a href={`#${contentId}`} data-control-ui="sidebar" data-control-family="sidebar" data-slot="skip-link" onClick={skipToContent}>
            {skipLinkLabel}
          </a>
          {children}
        </>
      ),
    },
  });

  return (
    <SidebarContext.Provider value={contextValue}>
      <SidebarElementsContext.Provider value={elements}>
        <TooltipProvider>{wrapper}</TooltipProvider>
      </SidebarElementsContext.Provider>
    </SidebarContext.Provider>
  );
}

"use client";

import { useRender } from "@base-ui/react/use-render";
import type { ComponentProps, CSSProperties, KeyboardEvent, MouseEvent, PointerEvent as ReactPointerEvent } from "react";
import { useEffect, useLayoutEffect, useRef, useState } from "react";
import type { SidebarKnobStyle } from "@/components/control-ui/knob-contracts/sidebar-knobs";
import { cn } from "@/components/control-ui/lib/cn";
import { useSidebar, useSidebarElements, useSidebarSurface } from "@/components/control-ui/ui/sidebar-provider";

const DRAG_THRESHOLD_PX = 5;
const KEYBOARD_STEP_PX = 10;

export type SidebarResizeRailProps = ComponentProps<"div"> & {
  style?: CSSProperties & SidebarKnobStyle;
};

export function SidebarResizeRail({ className, ref, onPointerDown, onClick, onKeyDown, ...props }: SidebarResizeRailProps) {
  const { open, setOpen, setWidth, toggleSidebar, minWidth, maxWidth } = useSidebar();
  const { wrapperRef, railRef } = useSidebarElements();
  const { side, collapsible } = useSidebarSurface();
  const widthMeasureRef = useRef<HTMLSpanElement>(null);
  const cancelGestureRef = useRef<(() => void) | null>(null);
  const draggedRef = useRef(false);
  const [measuredWidth, setMeasuredWidth] = useState<number>();

  useLayoutEffect(() => {
    const measure = widthMeasureRef.current;
    if (!measure) return;
    const updateMeasuredWidth = () => setMeasuredWidth(Math.round(measure.getBoundingClientRect().width));
    updateMeasuredWidth();
    const observer = new ResizeObserver(updateMeasuredWidth);
    observer.observe(measure);
    return () => observer.disconnect();
  }, []);

  useEffect(() => () => cancelGestureRef.current?.(), []);

  function clampWidth(nextWidth: number) {
    return Math.min(maxWidth, Math.max(minWidth, nextWidth));
  }

  function anchoredToLeftEdge(element: Element) {
    return (side === "left") === (getComputedStyle(element).direction !== "rtl");
  }

  function handlePointerDown(event: ReactPointerEvent<HTMLDivElement>) {
    onPointerDown?.(event);
    if (event.defaultPrevented || event.button !== 0) return;
    const mountedWrapper = wrapperRef.current;
    const measure = widthMeasureRef.current;
    if (!mountedWrapper || !measure) return;
    const wrapper = mountedWrapper;
    event.preventDefault();
    cancelGestureRef.current?.();
    draggedRef.current = false;
    const handle = event.currentTarget;
    handle.focus({ preventScroll: true });
    handle.setPointerCapture(event.pointerId);
    const pointerId = event.pointerId;
    const startX = event.clientX;
    const anchoredLeft = anchoredToLeftEdge(handle);
    const sidebarRoot = handle.closest('[data-control-family="sidebar"][data-slot="root"]') ?? wrapper;
    const sidebarBounds = sidebarRoot.getBoundingClientRect();
    const initialWidth = measure.getBoundingClientRect().width;
    const previousWidth = wrapper.style.getPropertyValue("--sidebar-width");
    const previousCursor = document.body.style.cursor;
    const previousUserSelect = document.body.style.userSelect;
    const controller = new AbortController();
    let draftWidth = initialWidth;
    const initiallyCollapsed = !open && collapsible !== "none";
    let collapsedDuringDrag = initiallyCollapsed;

    function restoreWidth() {
      wrapper.style.setProperty("--sidebar-width", previousWidth);
    }

    function endGesture() {
      controller.abort();
      document.body.style.cursor = previousCursor;
      document.body.style.userSelect = previousUserSelect;
      wrapper.removeAttribute("data-resizing");
      handle.removeAttribute("data-resizing");
      if (handle.hasPointerCapture(pointerId)) handle.releasePointerCapture(pointerId);
      cancelGestureRef.current = null;
    }

    function cancelGesture() {
      endGesture();
      restoreWidth();
      draggedRef.current = false;
      if (collapsedDuringDrag !== initiallyCollapsed) setOpen(open);
    }
    cancelGestureRef.current = cancelGesture;

    function updateCollapse(cursorWidth: number) {
      const shouldCollapse = collapsible !== "none" && cursorWidth < minWidth;
      if (shouldCollapse !== collapsedDuringDrag) {
        collapsedDuringDrag = shouldCollapse;
        setOpen(!shouldCollapse);
      }
      return shouldCollapse;
    }

    function movePointer(pointer: PointerEvent) {
      if (pointer.pointerId !== pointerId) return;
      const withinClickDistance = Math.abs(pointer.clientX - startX) <= DRAG_THRESHOLD_PX;
      if (!draggedRef.current && withinClickDistance) return;
      draggedRef.current = true;
      document.body.style.cursor = "col-resize";
      document.body.style.userSelect = "none";
      wrapper.setAttribute("data-resizing", "true");
      handle.setAttribute("data-resizing", "true");
      const cursorWidth = anchoredLeft ? pointer.clientX - sidebarBounds.left : sidebarBounds.right - pointer.clientX;
      if (updateCollapse(cursorWidth)) return;
      draftWidth = clampWidth(cursorWidth);
      wrapper.style.setProperty("--sidebar-width", `${draftWidth}px`);
    }

    function finishPointer(pointer: PointerEvent) {
      if (pointer.pointerId !== pointerId) return;
      endGesture();
      restoreWidth();
      if (draggedRef.current && !collapsedDuringDrag) setWidth(draftWidth);
    }

    function cancelPointer(pointer: PointerEvent) {
      if (pointer.pointerId === pointerId) cancelGesture();
    }

    function cancelWithEscape(keyboard: globalThis.KeyboardEvent) {
      if (keyboard.key !== "Escape") return;
      keyboard.preventDefault();
      cancelGesture();
    }

    window.addEventListener("pointermove", movePointer, { signal: controller.signal });
    window.addEventListener("pointerup", finishPointer, { signal: controller.signal });
    window.addEventListener("pointercancel", cancelPointer, { signal: controller.signal });
    handle.addEventListener("lostpointercapture", cancelPointer, { signal: controller.signal });
    window.addEventListener("blur", cancelGesture, { signal: controller.signal });
    window.addEventListener("keydown", cancelWithEscape, { signal: controller.signal });
  }

  function handleClick(event: MouseEvent<HTMLDivElement>) {
    onClick?.(event);
    if (event.defaultPrevented) return;
    if (draggedRef.current) {
      draggedRef.current = false;
      return;
    }
    if (collapsible !== "none") toggleSidebar();
  }

  function resizeWithArrow(expand: boolean) {
    if (isCollapsed) {
      if (expand) setOpen(true);
      return;
    }
    if (measuredWidth === undefined) return;
    const delta = expand ? KEYBOARD_STEP_PX : -KEYBOARD_STEP_PX;
    setWidth(clampWidth(measuredWidth + delta));
  }

  function expandToWidth(nextWidth: number) {
    if (collapsible !== "none") setOpen(true);
    setWidth(nextWidth);
  }

  function handleKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    onKeyDown?.(event);
    if (event.defaultPrevented) return;
    switch (event.key) {
      case "Enter":
      case " ":
        event.preventDefault();
        if (collapsible !== "none") toggleSidebar();
        return;
      case "Home":
      case "End":
        event.preventDefault();
        expandToWidth(event.key === "Home" ? minWidth : maxWidth);
        return;
      case "ArrowLeft":
      case "ArrowRight":
        event.preventDefault();
        resizeWithArrow(event.key === (anchoredToLeftEdge(event.currentTarget) ? "ArrowRight" : "ArrowLeft"));
        return;
    }
  }

  const isCollapsed = !open && collapsible !== "none";
  const widthDescription = measuredWidth === undefined ? undefined : `${measuredWidth} pixels`;
  return useRender({
    defaultTagName: "div",
    ref: [ref ?? null, railRef],
    props: {
      ...props,
      role: "separator",
      "aria-orientation": "vertical",
      "aria-label": props["aria-label"] ?? "Resize sidebar",
      "aria-valuenow": isCollapsed ? 0 : measuredWidth,
      "aria-valuemin": collapsible === "none" ? minWidth : 0,
      "aria-valuemax": maxWidth,
      "aria-valuetext": isCollapsed ? "collapsed" : widthDescription,
      tabIndex: 0,
      "data-control-ui": "sidebar",
      "data-control-family": "sidebar",
      "data-slot": "rail",
      "data-resizable": "",
      "data-resize-ready": measuredWidth === undefined ? undefined : "",
      onPointerDown: handlePointerDown,
      onClick: handleClick,
      onKeyDown: handleKeyDown,
      className: cn(
        "absolute inset-y-0 z-20 hidden cursor-col-resize touch-pan-y group-data-[side=left]:-end-1 group-data-[side=right]:-start-1 group-data-[side=left]:group-data-[collapsible=offcanvas]:-end-2 group-data-[side=right]:group-data-[collapsible=offcanvas]:-start-2 lg:block",
        className,
      ),
      children: (
        <>
          <span ref={widthMeasureRef} aria-hidden className="pointer-events-none invisible absolute w-(--sidebar-width)" />
          {props.children}
        </>
      ),
    },
  });
}

